try {
    throw new Exception("失敗");
    echo "A";
} catch (Exception $e) {
    echo "B";
}

$a = true and false;
$b = true && false;
echo (int)$a . "/" . (int)$b;

switch (2) {
    case 2: echo "X";
    case 3: echo "Y"; break;
}

function size(...$values) {
    return count($values);
}
echo size(4, 5);

class BaseLabel { public function text() { return "base"; } }
class ChildLabel extends BaseLabel { public function text() { return "child"; } }
echo (new ChildLabel())->text();

class Counter { public static $n = 0; }
Counter::$n += 3;
echo Counter::$n;

class Card { public $color = "red"; }
$a = new Card();
$b = $a;
$b->color = "blue";
echo $a->color;

class Box { public $n = 5; }
$a = new Box();
$b = clone $a;
$b->n = 9;
echo $a->n . "/" . $b->n;

class Animal {}
class Cat extends Animal {}
var_dump((new Cat()) instanceof Animal);

try {
    throw new Exception("stop");
    echo "T";
} catch (Exception $e) {
    echo "C";
} finally {
    echo "F";
}

